import React, { useState } from "react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Box,
  Typography,
  Tabs,
  Tab,
  Alert,
  Grid,
} from "@mui/material";

const ModalEdicion = ({ open, onClose, datos }) => {
  const [tabIndex, setTabIndex] = useState(0);
  const [formValues, setFormValues] = useState(datos || {});

  const handleTabChange = (event, newValue) => {
    setTabIndex(newValue);
  };

  const handleChange = (section, field, value) => {
    setFormValues((prev) => ({
      ...prev,
      [section]: {
        ...prev[section],
        [field]: value,
      },
    }));
  };

  const handleSubmit = () => {
    // Aquí iría la lógica para guardar los cambios
    console.log("Datos guardados:", formValues);
    onClose();
  };

  // Obtener las claves de las secciones dinámicamente
  const sections = Object.keys(datos || {});

  const currentSection = sections[tabIndex];

  // Función para renderizar los campos de la sección actual
  const renderFields = () => {
    const data = datos[currentSection];
    if (!data) {
      return (
        <Alert severity="info">
          No hay datos disponibles para editar en esta sección.
        </Alert>
      );
    }

    const entries = Object.entries(data);
    const totalFields = entries.length;

    if (totalFields === 0) {
      return (
        <Alert severity="info">
          No hay campos disponibles para editar en esta sección.
        </Alert>
      );
    }

    // Dividir los campos en columnas de hasta 8
    const columns = [];
    for (let i = 0; i < totalFields; i += 8) {
      columns.push(entries.slice(i, i + 8));
    }

    return (
      <Grid container spacing={2}>
        {columns.map((column, colIndex) => (
          <Grid item xs={12} md={6} key={colIndex}>
            {column.map(([key, value]) => (
              <TextField
                key={key}
                fullWidth
                label={key.charAt(0).toUpperCase() + key.slice(1)} // Capitalizar primera letra
                value={formValues[currentSection]?.[key] ?? value ?? ""}
                onChange={(e) =>
                  handleChange(currentSection, key, e.target.value)
                }
                margin="normal"
                variant="outlined"
              />
            ))}
          </Grid>
        ))}
      </Grid>
    );
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>Editar Contenido</DialogTitle>
      <DialogContent dividers>
        {sections.length > 0 ? (
          <>
            <Box sx={{ borderBottom: 1, borderColor: "divider", mb: 2 }}>
              <Tabs value={tabIndex} onChange={handleTabChange}>
                {sections.map((section, index) => (
                  <Tab
                    key={index}
                    label={section.charAt(0).toUpperCase() + section.slice(1)}
                  />
                ))}
              </Tabs>
            </Box>
            <Box>{renderFields()}</Box>
          </>
        ) : (
          <Alert severity="warning">
            No hay datos disponibles para editar.
          </Alert>
        )}
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} color="secondary">
          Cancelar
        </Button>
        <Button onClick={handleSubmit} color="primary">
          Guardar cambios
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ModalEdicion;
