"use client";

import React, { useState, useEffect } from "react";
import {
  Container,
  AppBar,
  Toolbar,
  Typography,
  Box,
  Paper,
  Menu,
  IconButton,
  Button,
  CircularProgress,
  Tabs,
  Tab,
  Alert,
  MenuItem,
} from "@mui/material";
import AccountCircleIcon from "@mui/icons-material/AccountCircle";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import axios from "axios";
import Swal from "sweetalert2";

import ClinicoTab from "@/components/ClinicoTab";
import HistoriaClinicaTab from "./components/HistoriaClinicaTab";
import FliaYApodTab from "./components/FliaYApodTab";
import InterconsultaTab from "./components/InterconsultaTab";
import ResumenHCTab from "./components/ResumenHCTab";

const Home = () => {
  const [cliente, setCliente] = useState(null);
  const [pacientes, setPacientes] = useState([]);
  const [selectedPaciente, setSelectedPaciente] = useState(null);
  const [anchorEl, setAnchorEl] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [tabIndex, setTabIndex] = useState(0);

  useEffect(() => {
    const fetchCliente = async () => {
      try {
        setLoading(true);
        const res = await axios.get("/api/cliente");
        setCliente(res.data);
      } catch (err) {
        console.error("Error al cargar cliente:", err);
        setError("No se pudo cargar la información del cliente");
        Swal.fire(
          "Error",
          "No se pudo cargar la información del cliente",
          "error"
        );
      } finally {
        setLoading(false);
      }
    };
    fetchCliente();
  }, []);

  useEffect(() => {
    const fetchPacientes = async () => {
      try {
        setLoading(true);
        const res = await axios.get("/api/pacientes");
        setPacientes(res.data);
      } catch (err) {
        console.error("Error al cargar pacientes:", err);
        setError("No se pudieron cargar los pacientes");
        Swal.fire("Error", "No se pudieron cargar los pacientes", "error");
      } finally {
        setLoading(false);
      }
    };
    if (cliente) {
      fetchPacientes();
    }
  }, [cliente]);

  const handleUserMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleUserMenuClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    Swal.fire({
      title: "¿Cerrar sesión?",
      text: "¿Estás seguro de que deseas salir?",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#3085d6",
      cancelButtonColor: "#d33",
      confirmButtonText: "Sí, salir",
      cancelButtonText: "Cancelar",
    }).then((result) => {
      if (result.isConfirmed) {
        Swal.fire("Sesión cerrada", "", "success");
      }
    });
    handleUserMenuClose();
  };

  const handleTabChange = (event, newValue) => {
    setTabIndex(newValue);
  };

  return (
    <Container maxWidth={false} sx={{ maxWidth: "100vw", padding: 0 }}>
      <AppBar position="static" color="default" elevation={1}>
        <Toolbar>
          <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
            Panel — Pacientes
          </Typography>
          <Box sx={{ display: "flex", alignItems: "center" }}>
            <IconButton
              size="large"
              edge="end"
              color="inherit"
              onClick={handleUserMenuOpen}
              aria-label="user menu"
            >
              <AccountCircleIcon />
              <Typography ml={1}>{cliente?.nombre || "Usuario"}</Typography>
              <ExpandMoreIcon />
            </IconButton>
            <Menu
              anchorEl={anchorEl}
              open={Boolean(anchorEl)}
              onClose={handleUserMenuClose}
            >
              <MenuItem onClick={handleLogout}>Cerrar sesión</MenuItem>
            </Menu>
          </Box>
        </Toolbar>
      </AppBar>

      <Box sx={{ padding: 3 }}>
        <Typography variant="h4" gutterBottom align="center">
          Seleccione un paciente
        </Typography>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {loading ? (
          <Box display="flex" justifyContent="center" my={4}>
            <CircularProgress />
          </Box>
        ) : (
          <>
            <Box sx={{ borderBottom: 1, borderColor: "divider", mb: 3 }}>
              <Tabs
                value={tabIndex}
                onChange={handleTabChange}
                variant="fullWidth"
              >
                <Tab label="Historia Clínica" />
                <Tab label="Clínico" />
                <Tab label="Resumen HC" />
                <Tab label="Información Familiar / Apoderado" />
                <Tab label="Interconsulta" />
              </Tabs>
            </Box>
            {tabIndex === 0 && (
              <HistoriaClinicaTab cliente={selectedPaciente} />
            )}
            {tabIndex === 1 && <ClinicoTab cliente={selectedPaciente} />}
            {tabIndex === 2 && <ResumenHCTab cliente={selectedPaciente} />}
            {tabIndex === 3 && <FliaYApodTab cliente={selectedPaciente} />}
            {tabIndex === 4 && <InterconsultaTab cliente={selectedPaciente} />}
          </>
        )}
      </Box>
    </Container>
  );
};

export default Home;
